    /// <summary>
    /// Adds ranges on order ID to the query that is used when data is created.
    /// Bug229943:CB887 - PO confirmed with missing barcode and unit price
    /// </summary>
    /// <param name="_datasourceRecordsPackedMap">
    /// A container with a packed version of a map with order IDs.
    /// </param>
    /// <param name="_abortOnError">
    /// A Boolean value that indicates whether to stop the update of the query if an error occurs.
    /// </param>
    /// <returns>
    /// The number of order ID ranges that are added to the query.
    /// </returns>
    /// <exception cref="M:Exception::Error">
    /// An error occurred during the update.
    /// </exception>
    protected int updateQueryDocumentRanges(container _datasourceRecordsPackedMap, boolean _abortOnError)
    {
        int ret = next updateQueryDocumentRanges(_datasourceRecordsPackedMap, _abortOnError);

        if (mayJournalBePostedMap != null)
        {
            if (!mayJournalBePostedMap.empty() && this is PurchFormletterParmDataPurchOrderConfirm)
            {
                MapEnumerator mapEnumerator = mayJournalBePostedMap.getEnumerator();

                while (mapEnumerator.moveNext())
                {
                    RefRecId recId = mapEnumerator.currentKey();

                    PurchTable purchTable = PurchTable::findRecId(recId);

                    if (purchTable)
                    {
                        purchTable.metCanPOBeConfirmed(purchTable);
                    }
                
                }
            }
        }
        
        return ret;
    }
